    def _detect_evidence_type(self, evidence: Dict[str, Any]) -> str:
        """
        Detect evidence type from evidence data structure.
        
        This replaces the complex @odata.type registry lookup with simple
        data structure analysis.
        """
        # Handle invalid evidence types
        if not evidence or not isinstance(evidence, dict):
            return "unknown"
            
        # Check @odata.type if available
        odata_type = evidence.get("@odata.type", "")
        if odata_type and isinstance(odata_type, str):
            odata_lower = odata_type.lower()
            if "deviceEvidence" in odata_lower:
                return "device"
            elif "processEvidence" in odata_lower:
                return "process"
            elif "userEvidence" in odata_lower:
                return "user"
            elif "fileEvidence" in odata_lower:
                return "file"
            elif "ipEvidence" in odata_lower:
                return "ip"
            elif "urlEvidence" in odata_lower:
                return "url"
            elif "registryKeyEvidence" in odata_lower:
                return "registry_key"
            elif "registryValueEvidence" in odata_lower:
                return "registry_value"
            elif "cloudApplicationEvidence" in odata_lower:
                return "cloud_app"
            elif "oAuthApplicationEvidence" in odata_lower:
                return "oauth_app"
            
        # Fallback to data structure analysis
        if "deviceId" in evidence or "hostname" in evidence or "deviceDnsName" in evidence:
            return "device"
        elif "processId" in evidence or "commandLine" in evidence:
            return "process"
        elif "userId" in evidence or "userPrincipalName" in evidence:
            return "user"
        elif "fileName" in evidence or "fileHash" in evidence:
            return "file"
        elif "ipAddress" in evidence:
            return "ip"
        elif "url" in evidence:
            return "url"
        elif "registryKey" in evidence and "registryValue" not in evidence:
            return "registry_key"
        elif "registryValue" in evidence:
            return "registry_value"
        elif "appId" in evidence and "publisher" not in evidence:
            return "cloud_app"
        elif "appId" in evidence and "publisher" in evidence:
            return "oauth_app"
            
        return "unknown"
    
    def _ensure_field(self, hit: Hit, field_name: str, field_class) -> Any:
        """
        Ensure a field exists on the hit object, creating it if necessary.
        
        This replaces the complex try/catch patterns with simple existence checks.
        """
        if not hasattr(hit, field_name) or getattr(hit, field_name) is None:
            setattr(hit, field_name, field_class())
        return getattr(hit, field_name)
    
    def _add_tags(self, hit: Hit, tags: List[str]) -> None:
        """Add tags to hit, ensuring no duplicates."""
        if not hit.tags:
            hit.tags = []
        for tag in tags:
            if tag not in hit.tags:
                hit.tags.append(tag)
    
    def _map_device_evidence(self, evidence: Dict[str, Any], hit: Hit) -> Hit:
        """Map device evidence to ECS host fields."""
        host = self._ensure_field(hit, "host", Host)
        
        # Map device fields with simple .get() instead of safe_get()
        device_id = evidence.get("deviceId")
        if device_id:
            host.id = device_id
            
        hostname = evidence.get("hostname") or evidence.get("deviceName") or evidence.get("deviceDnsName")
        if hostname:
            host.name = hostname
            
        os_platform = evidence.get("osPlatform")
        if os_platform:
            if not host.os:
                host.os = {}
            host.os["platform"] = os_platform.lower()
            
        # Add device-specific tags
        tags = ["device:activity"]
        if os_platform:
            tags.append(f"device:os:{os_platform.lower()}")
        self._add_tags(hit, tags)
        
        return hit
    
    def _map_process_evidence(self, evidence: Dict[str, Any], hit: Hit) -> Hit:
        """Map process evidence, caching for hierarchy building."""
        # Cache process evidence for hierarchy building
        self._process_cache.append(evidence)
        
        # If this is the first process, set as primary
        if not hasattr(hit, "process") or hit.process is None:
            process = self._ensure_field(hit, "process", Process)
            
            command_line = evidence.get("commandLine")
            if command_line:
                process.command_line = command_line
                
            process_id = evidence.get("processId")
            if process_id is not None:
                process.pid = int(process_id) if str(process_id).isdigit() else None
                
            process_name = evidence.get("processName") or evidence.get("fileName")
            if process_name:
                process.name = process_name
                
            # Add process tags
            self._add_tags(hit, ["process:activity"])
            
        return hit
    
    def _map_user_evidence(self, evidence: Dict[str, Any], hit: Hit) -> Hit:
        """Map user evidence to ECS user fields."""
        user = self._ensure_field(hit, "user", ECSUser)
        
        user_id = evidence.get("userId")
        if user_id:
            user.id = user_id
            
        upn = evidence.get("userPrincipalName")
        if upn:
            user.email = upn
            if "@" in upn:
                user.name = upn.split("@")[0]
                user.domain = upn.split("@")[1]
            else:
                user.name = upn
                
        display_name = evidence.get("displayName")
        if display_name:
            user.full_name = display_name
            
        # Add user tags
        tags = ["user:activity"]
        if user.domain:
            tags.append(f"user:domain:{user.domain}")
        self._add_tags(hit, tags)
        
        return hit
    
    def _map_file_evidence(self, evidence: Dict[str, Any], hit: Hit) -> Hit:
        """Map file evidence to ECS file fields."""
        file_details = evidence.get("fileDetails") or evidence
        
        # Only create primary file if none exists
        if not hasattr(hit, "file") or hit.file is None:
            file_obj = self._ensure_field(hit, "file", File)
            
            file_name = file_details.get("fileName")
            if file_name:
                file_obj.name = file_name
                if "." in file_name:
                    file_obj.extension = file_name.split(".")[-1].lower()
                    
            file_path = file_details.get("filePath")
            if file_path:
                file_obj.directory = file_path
                if file_name:
                    separator = "/" if "/" in file_path else "\\"
                    if not file_path.endswith(separator):
                        file_path += separator
                    file_obj.path = file_path + file_name
                    
            file_size = file_details.get("fileSize")
            if file_size is not None:
                try:
                    file_obj.size = int(file_size)
                except (ValueError, TypeError):
                    pass
                    
            # Map file hashes
            file_obj.hash = self._extract_file_hashes(file_details)
            
        else:
            # Add as file context via tags
            file_name = file_details.get("fileName")
            if file_name:
                self._add_tags(hit, [f"file:{file_name}"])
                
        self._add_tags(hit, ["file:activity"])
        return hit
    
    def _map_ip_evidence(self, evidence: Dict[str, Any], hit: Hit) -> Hit:
        """Map IP evidence to ECS host fields."""
        ip_address = evidence.get("ipAddress")
        if ip_address:
            # Validate IP address before setting it
            try:
                ipaddress.ip_address(ip_address)
                # Add IP to host.ip list
                host = self._ensure_field(hit, "host", Host)
                if not hasattr(host, "ip") or host.ip is None:
                    host.ip = []
                if ip_address not in host.ip:
                    host.ip.append(ip_address)
                
                # Add IP tags
                self._add_tags(hit, ["ip:activity", f"ip:{ip_address}"])
            except (ValueError, TypeError) as e:
                # Log warning for invalid IP address but continue processing
                self.logger.warning("Invalid IP address in evidence: %s", ip_address)
                # Add as a tag for tracking even if invalid
                self._add_tags(hit, ["ip:invalid"])
            
        return hit
    
    def _map_url_evidence(self, evidence: Dict[str, Any], hit: Hit) -> Hit:
        """Map URL evidence to ECS URL fields."""
        url = self._ensure_field(hit, "url", URL)
        
        url_string = evidence.get("url")
        if url_string:
            url.full = url_string
            
            try:
                parsed = urlparse(url_string)
                if parsed.scheme:
                    url.scheme = parsed.scheme
                if parsed.netloc:
                    url.domain = parsed.netloc
                if parsed.path:
                    url.path = parsed.path
                if parsed.query:
                    url.query = parsed.query
                if parsed.port:
                    url.port = parsed.port
                    
                # Add URL tags
                tags = ["url:accessed"]
                if parsed.netloc:
                    tags.append(f"url:domain:{parsed.netloc}")
                if parsed.scheme:
                    tags.append(f"url:scheme:{parsed.scheme}")
                self._add_tags(hit, tags)
                
            except Exception as e:
                self.logger.warning("Failed to parse URL %s: %s", url_string, str(e))
                
        return hit
    
