    def _extract_file_hashes(self, file_details: Dict[str, Any]) -> Optional[Hashes]:
        """Extract file hashes from file details."""
        hashes = Hashes()
        hash_found = False
        
        def _validate_hash(hash_value: str, hash_type: str) -> bool:
            """Validate that hash is a valid hexadecimal string."""
            if not hash_value or not isinstance(hash_value, str):
                return False
            # Remove any whitespace and convert to lowercase
            hash_value = hash_value.strip().lower()
            # Check if it's a valid hex string and appropriate length
            expected_lengths = {"md5": 32, "sha1": 40, "sha256": 64}
            expected_length = expected_lengths.get(hash_type)
            try:
                int(hash_value, 16)  # Validate hex format
                return len(hash_value) == expected_length if expected_length else True
            except ValueError:
                self.logger.warning("Invalid %s hash format: %s", hash_type, hash_value)
                return False
        
        md5_hash = file_details.get("md5") or file_details.get("fileHashMd5")
        if md5_hash and _validate_hash(md5_hash, "md5"):
            hashes.md5 = md5_hash.strip().lower()
            hash_found = True
            
        sha1_hash = file_details.get("sha1") or file_details.get("fileHashSha1")
        if sha1_hash and _validate_hash(sha1_hash, "sha1"):
            hashes.sha1 = sha1_hash.strip().lower()
            hash_found = True
            
        sha256_hash = file_details.get("sha256") or file_details.get("fileHashSha256")
        if sha256_hash and _validate_hash(sha256_hash, "sha256"):
            hashes.sha256 = sha256_hash.strip().lower()
            hash_found = True
            
        return hashes if hash_found else None
    
